import logging
import threading
import time
from email.utils import parsedate_to_datetime
from urllib.parse import urlparse

import httpx

log = logging.getLogger("http")


class NotFound(Exception):
    pass


class HttpError(Exception):
    pass


class SchemaError(Exception):
    pass


class RateLimiter:
    def __init__(self, min_interval: float, sleep=time.sleep, clock=time.monotonic):
        self.min_interval = min_interval
        self._sleep = sleep
        self._clock = clock
        self._lock = threading.Lock()
        self._last: dict[str, float] = {}

    def wait(self, host: str) -> None:
        with self._lock:
            now = self._clock()
            ready_at = self._last.get(host, float("-inf")) + self.min_interval
            delay = max(0.0, ready_at - now)
            self._last[host] = now + delay
        if delay:
            self._sleep(delay)


def retry_after_seconds(value: str | None, cap: float = 60.0) -> float | None:
    if not value:
        return None
    value = value.strip()
    if value.isdigit():
        return min(float(value), cap)
    try:
        when = parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return None
    if when is None:
        return None
    delta = when.timestamp() - time.time()
    return min(max(delta, 0.0), cap)


class PoliteClient:
    def __init__(self, user_agent: str, min_interval: float = 1.1, timeout: float = 30.0,
                 retries: int = 3, backoff_base: float = 2.0, on_request=None, transport=None,
                 sleep=time.sleep):
        self.limiter = RateLimiter(min_interval, sleep=sleep)
        self.retries = retries
        self.backoff_base = backoff_base
        self.on_request = on_request
        self._sleep = sleep
        self.client = httpx.Client(
            timeout=timeout,
            follow_redirects=True,
            headers={"User-Agent": user_agent, "Accept-Language": "en-US,en;q=0.9"},
            transport=transport,
        )

    def get(self, url: str, params: dict | None = None, headers: dict | None = None,
            cookies: dict | None = None) -> httpx.Response:
        host = urlparse(url).netloc
        last_exc: Exception | None = None
        for attempt in range(self.retries + 1):
            self.limiter.wait(host)
            wait = self.backoff_base * (2 ** attempt)
            try:
                resp = self.client.get(url, params=params, headers=headers, cookies=cookies)
            except httpx.HTTPError as exc:
                last_exc = HttpError(f"{exc.__class__.__name__}: {exc}" if str(exc) else exc.__class__.__name__)
                self.report(host, False)
                log.warning("GET %s failed (%s), attempt %d", url, exc.__class__.__name__, attempt + 1)
            else:
                if resp.status_code == 404:
                    self.report(host, True)
                    raise NotFound(url)
                if resp.status_code == 429 or resp.status_code >= 500:
                    last_exc = HttpError(f"HTTP {resp.status_code} for {url}")
                    self.report(host, False)
                    log.warning("GET %s -> %d, attempt %d", url, resp.status_code, attempt + 1)
                    hinted = retry_after_seconds(resp.headers.get("retry-after"))
                    if hinted is not None:
                        wait = max(wait, hinted)
                elif resp.status_code >= 400:
                    self.report(host, False)
                    raise HttpError(f"HTTP {resp.status_code} for {url}")
                else:
                    self.report(host, True)
                    return resp
            if attempt < self.retries:
                self._sleep(wait)
        raise HttpError(str(last_exc) if last_exc else f"GET {url} failed")

    def report(self, host: str, ok: bool) -> None:
        if self.on_request:
            try:
                self.on_request(host, ok)
            except Exception:
                pass

    def close(self) -> None:
        self.client.close()
import logging
import threading
from collections import deque
from datetime import datetime, timezone, tzinfo

from .config import iso, utcnow

WORKER_TITLES = {
    "scheduler": "Планировщик",
    "pipeline": "Обработчик игр",
    "metacritic": "Metacritic",
    "youtube": "YouTube",
    "llm": "LLM",
}


class Monitor:
    def __init__(self, log_size: int = 400, tz: tzinfo = timezone.utc):
        self.tz = tz
        self._lock = threading.Lock()
        self.version = 0
        self._log: deque = deque(maxlen=log_size)
        self._log_seq = 0
        self.workers: dict[str, dict] = {
            name: {"name": name, "title": title, "status": "idle", "detail": "", "updated_at": iso(utcnow())}
            for name, title in WORKER_TITLES.items()
        }
        self.counters = {
            "metacritic_ok": 0, "metacritic_failed": 0,
            "youtube_ok": 0, "youtube_failed": 0,
            "llm_ok": 0, "llm_failed": 0, "llm_last_latency": None,
        }
        self.progress = {"run_id": None, "done": 0, "total": 0, "ok": 0, "failed": 0, "current": None,
                         "step": None, "started_at": None}
        self.next_run_at: str | None = None
        self.started_at = iso(utcnow())

    def _bump(self) -> None:
        self.version += 1

    def set_worker(self, name: str, status: str, detail: str = "") -> None:
        with self._lock:
            w = self.workers[name]
            w.update(status=status, detail=detail, updated_at=iso(utcnow()))
            self._bump()

    def set_progress(self, **kwargs) -> None:
        with self._lock:
            self.progress.update(kwargs)
            self._bump()

    def reset_progress(self) -> None:
        with self._lock:
            self.progress = {"run_id": None, "done": 0, "total": 0, "ok": 0, "failed": 0, "current": None,
                             "step": None, "started_at": None}
            self._bump()

    def set_next_run(self, when) -> None:
        with self._lock:
            self.next_run_at = iso(when) if when else None
            self._bump()

    def http_event(self, host: str, ok: bool) -> None:
        key = "youtube" if "youtube" in host else "metacritic" if "metacritic" in host else None
        if not key:
            return
        with self._lock:
            self.counters[f"{key}_{'ok' if ok else 'failed'}"] += 1
            w = self.workers[key]
            w["status"] = "ok" if ok else "error"
            w["detail"] = f"запросов: {self.counters[key + '_ok']} успешных, {self.counters[key + '_failed']} с ошибкой"
            w["updated_at"] = iso(utcnow())
            self._bump()

    def llm_event(self, ok: bool, latency: float) -> None:
        with self._lock:
            self.counters["llm_ok" if ok else "llm_failed"] += 1
            self.counters["llm_last_latency"] = round(latency, 1)
            w = self.workers["llm"]
            w["status"] = "ok" if ok else "error"
            w["detail"] = (f"вызовов: {self.counters['llm_ok']} успешных, {self.counters['llm_failed']} с ошибкой; "
                           f"последний ответ за {latency:.1f} с")
            w["updated_at"] = iso(utcnow())
            self._bump()

    def add_log(self, record: logging.LogRecord, message: str) -> None:
        with self._lock:
            self._log_seq += 1
            self._log.append({
                "id": self._log_seq,
                "ts": datetime.fromtimestamp(record.created, self.tz).strftime("%H:%M:%S"),
                "level": record.levelname,
                "logger": record.name,
                "message": message,
            })
            self._bump()

    def logs_since(self, last_id: int = 0, limit: int = 200) -> list[dict]:
        with self._lock:
            items = [e for e in self._log if e["id"] > last_id]
        return items[-limit:]

    def snapshot(self) -> dict:
        with self._lock:
            return {
                "version": self.version,
                "workers": [dict(w) for w in self.workers.values()],
                "counters": dict(self.counters),
                "progress": dict(self.progress),
                "next_run_at": self.next_run_at,
                "started_at": self.started_at,
            }


class MonitorLogHandler(logging.Handler):
    def __init__(self, monitor: Monitor):
        super().__init__(level=logging.INFO)
        self.monitor = monitor

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.monitor.add_log(record, record.getMessage())
        except Exception:
            pass


